package dev.cosmerearcanists.power;
import java.util.*;
import com.mojang.authlib.GameProfile;
import dev.cosmerearcanists.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.item.*;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class GoldGameTests {
    private static FakePlayer player(GameTestHelper h){var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"GoldTest"));p.setPos(net.minecraft.world.phys.Vec3.atCenterOf(h.absolutePos(new net.minecraft.core.BlockPos(1,20,1))));return p;}
    private static void ready(FakePlayer p){PowerAttributes.set(p,"a:gold",1);PowerData.reserve(p,"gold",PowerConfig.RESERVE_CAP.get());PowerData.state(p,"a:gold",2);}
    private static void age(FakePlayer p){PowerData.data(p).getCompound(GoldService.KEY).putLong("lastTick",p.server.overworld().getGameTime()-GoldConfig.INTERVAL.get());}
    @GameTest(template="empty") public static void recordsBeforeGoldAndPreservesHistoricalEquipmentPowersAndOrigin(GameTestHelper h){var p=player(h);new OriginData("scadrial","human","steel","iron").save(p);PowerAttributes.set(p,"a:steel",2);p.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.IRON_HELMET));p.experienceLevel=7;SpiritualIntegrity.set(p,.4);h.assertTrue(GoldService.record(p),"History starts before gold is acquired");var first=GoldService.history(p).getFirst();p.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.DIAMOND_HELMET));PowerAttributes.set(p,"a:steel",3);SpiritualIntegrity.set(p,.8);
        h.assertTrue(first.getList("equipment",Tag.TAG_STRING).getString(5).equals("minecraft:iron_helmet")&&first.getCompound("powers").getDouble("a:steel")==2&&first.getDouble("integrity")==.4&&first.getString("planet").equals("scadrial")&&first.getInt("level")==7,"Snapshots preserve original values without inventory copies");first.putInt("level",999);h.assertTrue(GoldService.history(p).getFirst().getInt("level")==7,"Returned history is detached from saved data");h.assertTrue(!GoldService.record(p),"Rapid changes cannot spam snapshots");age(p);h.assertTrue(GoldService.record(p)&&GoldService.history(p).size()==2,"A later changed version is recorded");age(p);h.assertTrue(!GoldService.record(p)&&GoldService.history(p).size()==2,"Unchanged periodic duplicates do not displace meaningful history");h.succeed();}
    @GameTest(template="empty") public static void historyIsBoundedAndPersistsThroughPlayerClone(GameTestHelper h){var p=player(h);for(int i=0;i<GoldConfig.LIMIT.get()+3;i++){p.experienceLevel=i;age(p);GoldService.record(p);}var history=GoldService.history(p);h.assertTrue(history.size()==GoldConfig.LIMIT.get()&&history.getFirst().getLong("sequence")==1&&history.get(1).getLong("sequence")==5,"The first self is retained while recent changes expire at the configured bound");var clone=player(h);PowerData.clonePlayer(p,clone);h.assertTrue(GoldService.history(clone).equals(history),"History survives respawn copy");h.assertTrue(!PowerData.data(p).getCompound(GoldService.KEY).toString().contains("Items"),"History stores no usable item inventories");h.succeed();}
    @GameTest(template="empty") public static void selectsPastVersionsAndScalesAccessWithoutRestoringTheirState(GameTestHelper h){var p=player(h);ready(p);for(int i=0;i<8;i++){p.experienceLevel=i;age(p);GoldService.record(p);}h.assertTrue(GoldService.selected(p).getInt("level")==6,"Default vision skips the matching current version");int normal=GoldService.accessible(p);PowerData.state(p,"a:gold",1);int low=GoldService.accessible(p);PowerData.state(p,"a:gold",3);int flare=GoldService.accessible(p);h.assertTrue(low<normal&&normal<flare,"Burn levels unlock more recorded versions");PowerAttributes.set(p,"a:gold",4);h.assertTrue(GoldService.accessible(p)>flare,"Higher attributes increase accessible history");var before=p.getPersistentData().copy();var selected=GoldService.selected(p);GoldService.details(p,selected);h.assertTrue(p.experienceLevel==7&&PowerAttributes.strength(p,"a:gold")==4&&p.getPersistentData().equals(before),"Viewing is read-only and never restores levels or powers");h.succeed();}
    @GameTest(template="empty") public static void goldFuelEnhancementsAndDisabledHistoryPreserveSavedData(GameTestHelper h){var p=player(h);ready(p);GoldService.record(p);PowerAttributes.set(p,"a:duralumin",1);PowerData.reserve(p,"duralumin",100);PowerData.state(p,"a:duralumin",1);h.assertTrue(GoldService.strength(p)==1.75&&SeekingService.activeStrength(p,"a:gold")==1.75,"Gold participates in enhancement and bronze signal services");double fuel=PowerData.reserve(p,"gold");GoldService.tick(p);h.assertTrue(Math.abs(fuel-PowerData.reserve(p,"gold")-GoldConfig.DRAIN.get()/20*5)<1e-7,"Duralumin scales passive gold consumption");boolean enabled=GoldConfig.ENABLED.get();var saved=GoldService.history(p);fuel=PowerData.reserve(p,"gold");try{GoldConfig.ENABLED.set(false);GoldService.tick(p);h.assertTrue(GoldService.strength(p)==0&&GoldService.accessible(p)==0&&!GoldService.record(p)&&GoldService.history(p).equals(saved)&&PowerData.reserve(p,"gold")==fuel,"Disabling preserves history, powers and unspent reserve");}finally{GoldConfig.ENABLED.set(enabled);}PowerData.reserve(p,"gold",.001);GoldService.tick(p);h.assertTrue(PowerData.state(p,"a:gold")==0,"Depletion stops gold");h.succeed();}
    @GameTest(template="empty") public static void historicalVisionPacketRoundTripsAndRejectsInvalidSizes(GameTestHelper h){var p=player(h);ready(p);GoldService.record(p);var packet=new GoldPacket(p.level().dimension().location().toString(),20,p.position(),45,.4f,Collections.nCopies(6,"minecraft:air"),GoldService.details(p,GoldService.selected(p)));var b=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{GoldPacket.CODEC.encode(b,packet);h.assertTrue(GoldPacket.CODEC.decode(b).equals(packet),"Private historical display safely round trips");}finally{b.release();}boolean rejected=false;try{new GoldPacket("minecraft:overworld",20,p.position(),0,.4f,List.of(),List.of());}catch(IllegalArgumentException expected){rejected=true;}h.assertTrue(rejected,"Invalid equipment count is rejected");h.succeed();}
    @GameTest(template="empty") public static void alternateActivationCyclesHistoryOnEitherPowerSlot(GameTestHelper h){var p=player(h);ready(p);for(int i=0;i<5;i++){p.experienceLevel=i;age(p);GoldService.record(p);}h.assertTrue(GoldService.selected(p).getInt("level")==3,"Starts at most recent past version");PowerData.assignSlot(p,"a:gold",0);PowerService.control(p,new PowerNetwork.Control(2,"",3));GoldService.activate(p,"a:gold",AbilityDispatcher.Phase.START);h.assertTrue(GoldService.selected(p).getInt("level")==2,"Alt and primary activation select an older version");GoldService.activate(p,"a:gold",AbilityDispatcher.Phase.TICK);h.assertTrue(GoldService.selected(p).getInt("level")==2,"Holding does not cycle every tick");PowerService.control(p,new PowerNetwork.Control(2,"",0));PowerData.assignSlot(p,"a:gold",1);PowerService.control(p,new PowerNetwork.Control(7,"",3));GoldService.activate(p,"a:gold",AbilityDispatcher.Phase.START);h.assertTrue(GoldService.selected(p).getInt("level")==1,"Secondary Alt activation also cycles history");PowerService.control(p,new PowerNetwork.Control(7,"",0));h.succeed();}
    private GoldGameTests(){}
}
